// Some portions generated by Co-Pilot
"use client";

import React, { memo, useState, useEffect } from "react";
import { useLocale, useTranslations } from "next-intl";
import { FiArrowUpRight } from "react-icons/fi";
import ClientPagination from "./ClientPagination";
import { truncateIfLonger } from "@/utils/truncateLonger";
import { fetchLatestEvents } from "@/hooks";

// Define a type for events
interface TimelineEvent {
  date: string;
  title: string;
  description: string;
  infoLink: string;
}

// Accept data as a prop for testing, fallback to fetchLatestEvents if not provided
interface TimeLineProps {
  data?: TimelineEvent[];
}

const TimeLine = ({ data }: TimeLineProps) => {
  const locale = useLocale();
  const t = useTranslations("ModernPages.events");
  const [events, setEvents] = useState<TimelineEvent[]>(data || []);

  useEffect(() => {
    if (!data) {
      // Fetch actual events from API
      const getEvents = async () => {
        const response = await fetchLatestEvents();
        setEvents(response);
      };
      getEvents();
    }
  }, [data]);

  const validEvents = events?.filter(
    (event) => !!event.date && !isNaN(new Date(event.date).getTime()),
  );

  const totalCount = validEvents?.length || 0;
  const postsPerPage = 6;
  const totalPages = Math.ceil(totalCount / postsPerPage);
  const [currentPage, setCurrentPage] = useState<number>(1);

  const startIndex = (currentPage - 1) * postsPerPage;
  const endIndex = startIndex + postsPerPage;
  const paginatedData = validEvents.slice(startIndex, endIndex);

  // Helper for date formatting
  const newDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString(locale, {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  };

  return (
    <div>
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {paginatedData.map((event, index) => {
          return (
            <article
              key={index}
              className="min-w-0 rounded-2xl border border-white/10 bg-white/[0.025] p-6"
            >
              <time
                dateTime={event.date}
                className="text-xs font-medium text-[#ff91b7]"
              >
                {newDate(event.date)}
              </time>
              <h3 className="mb-3 mt-4 text-xl font-semibold leading-snug">
                <a
                  href={event.infoLink}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="hover:text-[#ff91b7] focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-pink"
                >
                  <span className="mr-1">{event.title}</span>
                  <FiArrowUpRight
                    className="inline"
                    size={16}
                    aria-hidden="true"
                  />
                </a>
              </h3>
              <p className="mb-0 text-sm leading-relaxed text-grey">
                {truncateIfLonger(event.description)}
              </p>
            </article>
          );
        })}
      </div>
      {data && paginatedData.length === 0 && (
        <p className="rounded-2xl border border-white/10 p-6 text-sm text-grey">
          {t("empty")}
        </p>
      )}
      <ClientPagination
        currentPage={currentPage}
        totalPages={totalPages}
        onNavigate={setCurrentPage}
      />
      <div className="mt-6 flex flex-wrap items-center justify-between gap-4 border-t border-white/10 pt-6 text-sm text-[#ff91b7]">
        <a
          href="https://events.eclipse.org/"
          target="_blank"
          rel="noopener noreferrer"
          className="flex items-center gap-3"
        >
          <span>{t("all-events")}</span>
          <FiArrowUpRight aria-hidden="true" />
        </a>
        <a
          href="https://newsroom.eclipse.org/node/add/events"
          target="_blank"
          rel="noopener noreferrer"
          className="flex items-center gap-3"
        >
          <span>{t("submit")}</span>
          <FiArrowUpRight aria-hidden="true" />
        </a>
      </div>
    </div>
  );
};

export default memo(TimeLine);
